// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListDiscardedJobs Background jobs that failed every attempt, newest first
	// (GET /admin/jobs/discarded)
	ListDiscardedJobs(w http.ResponseWriter, r *http.Request, params ListDiscardedJobsParams)
	// DeleteDiscardedJob Delete a discarded job
	// (DELETE /admin/jobs/discarded/{job_id})
	DeleteDiscardedJob(w http.ResponseWriter, r *http.Request, jobId JobID)
	// RetryDiscardedJob Run a discarded job again
	// (POST /admin/jobs/discarded/{job_id}/retry)
	RetryDiscardedJob(w http.ResponseWriter, r *http.Request, jobId JobID)
	// ListMarkupRules Every markup rule, from the least to the most specific scope
	// (GET /admin/markup-rules)
	ListMarkupRules(w http.ResponseWriter, r *http.Request)
	// CreateMarkupRule Add a markup rule
	// (POST /admin/markup-rules)
	CreateMarkupRule(w http.ResponseWriter, r *http.Request)
	// DeleteMarkupRule Delete a markup rule
	// (DELETE /admin/markup-rules/{rule_id})
	DeleteMarkupRule(w http.ResponseWriter, r *http.Request, ruleId int64)
	// UpdateMarkupRule Change a markup rule
	// (PUT /admin/markup-rules/{rule_id})
	UpdateMarkupRule(w http.ResponseWriter, r *http.Request, ruleId int64)
	// GetAdminOverview The numbers on the admin dashboard
	// (GET /admin/overview)
	GetAdminOverview(w http.ResponseWriter, r *http.Request)
	// ListAdminProducts Every product with its dealer price, margin and markup rule, by name
	// (GET /admin/products)
	ListAdminProducts(w http.ResponseWriter, r *http.Request, params ListAdminProductsParams)
	// ListSpecsReviewQueue Builder parts whose specs are incomplete, waiting longest first
	// (GET /admin/specs/review-queue)
	ListSpecsReviewQueue(w http.ResponseWriter, r *http.Request, params ListSpecsReviewQueueParams)
	// GetProductSpecs A builder part's canonical fields with the supplier's, the admin's and the effective values
	// (GET /admin/specs/{product_id})
	GetProductSpecs(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// UpdateProductSpecs Set or clear admin values
	// (PATCH /admin/specs/{product_id})
	UpdateProductSpecs(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// TriggerSync Sync the catalog with the supplier now
	// (POST /admin/sync)
	TriggerSync(w http.ResponseWriter, r *http.Request)
	// ListSyncRuns Supplier sync runs, newest first
	// (GET /admin/sync-runs)
	ListSyncRuns(w http.ResponseWriter, r *http.Request, params ListSyncRunsParams)
	// Login Log in with email and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Log out
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The logged-in user
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ConfirmTotp Finish setting up TOTP with a first code
	// (POST /auth/totp/confirm)
	ConfirmTotp(w http.ResponseWriter, r *http.Request)
	// EnrollTotp Start setting up TOTP
	// (POST /auth/totp/enroll)
	EnrollTotp(w http.ResponseWriter, r *http.Request)
	// RegenerateRecoveryCodes Replace the recovery codes
	// (POST /auth/totp/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// VerifyTotp Pass the second factor with a TOTP or recovery code
	// (POST /auth/totp/verify)
	VerifyTotp(w http.ResponseWriter, r *http.Request)
	// CheckBuild Check a PC build's compatibility, power draw and price
	// (GET /builder/check)
	CheckBuild(w http.ResponseWriter, r *http.Request, params CheckBuildParams)
	// ListBuilderOptions The parts that fit a slot of a PC build
	// (GET /builder/options)
	ListBuilderOptions(w http.ResponseWriter, r *http.Request, params ListBuilderOptionsParams)
	// SaveBuild Save a PC build to share
	// (POST /builds)
	SaveBuild(w http.ResponseWriter, r *http.Request)
	// GetBuild A saved PC build, checked again at today's parts and prices
	// (GET /builds/{slug})
	GetBuild(w http.ResponseWriter, r *http.Request, slug string)
	// GetCart The shopper's cart at today's prices
	// (GET /cart)
	GetCart(w http.ResponseWriter, r *http.Request)
	// AddToCart Add products to the cart
	// (POST /cart/lines)
	AddToCart(w http.ResponseWriter, r *http.Request)
	// RemoveFromCart Take a product out of the cart
	// (DELETE /cart/lines/{product_id})
	RemoveFromCart(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// SetCartQuantity Change how many of a product the cart holds
	// (PUT /cart/lines/{product_id})
	SetCartQuantity(w http.ResponseWriter, r *http.Request, productId openapi_types.UUID)
	// GetHealth Health summary
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// ListProducts List the products shoppers can see
	// (GET /products)
	ListProducts(w http.ResponseWriter, r *http.Request, params ListProductsParams)
	// GetProduct Product page data
	// (GET /products/{slug})
	GetProduct(w http.ResponseWriter, r *http.Request, slug string)
	// SearchProducts Search and filter the products shoppers can see, with facet counts
	// (GET /search)
	SearchProducts(w http.ResponseWriter, r *http.Request, params SearchProductsParams)
}

